import React, { useState, useEffect, useRef, useCallback } from 'react';
import axios from 'axios';
import './App.css';

// Server URL for backend
const SERVER_URL = 'http://localhost:3001';

// Placeholder image for browser preview
const PLACEHOLDER_IMAGE = 'data:image/png;base64,';

/**
 * OpenAI MCP Client
 */
function App() {
    // Core state
    const [sessionId, setSessionId] = useState(null);
    const [messages, setMessages] = useState([
        {
            role: 'assistant',
            content: 'Welcome! I\'m here to help you with your questions and tasks. How can I assist you today?'
        }
    ]);
    const [inputValue, setInputValue] = useState('');
    const [loading, setLoading] = useState(false);
    const [error, setError] = useState(null);
    const [streamingContent, setStreamingContent] = useState(''); // For storing partial responses

    // Preview state
    const [browserImage, setBrowserImage] = useState(PLACEHOLDER_IMAGE);
    const [previewVisible, setPreviewVisible] = useState(true);
    const [streaming, setStreaming] = useState(false);
    const [streamStatus, setStreamStatus] = useState('waiting');

    // Status messages
    const [statusMessages, setStatusMessages] = useState([{
        type: 'info',
        text: 'Initializing...',
        time: new Date().toLocaleTimeString()
    }]);
    const [showTechnicalMessages, setShowTechnicalMessages] = useState(false);

    // Refs for tracking state and timeouts
    const messagesRef = useRef([]);
    const loadingRef = useRef(false);
    const pollTimerRef = useRef(null);
    const messagesEndRef = useRef(null);
    const streamSourceRef = useRef(null);
    const sessionIdRef = useRef(null);
    const chatContainerRef = useRef(null);
    const [showScrollButton, setShowScrollButton] = useState(false);
    const [scrollButtonPosition, setScrollButtonPosition] = useState(typeof window !== 'undefined' ? window.innerHeight - 70 : 0); // Position from top

    // Constants
    const POLL_INTERVAL = 2000; // 2 seconds

    // Update refs when state changes
    useEffect(() => {
        const prevMessages = messagesRef.current;
        messagesRef.current = messages;

        // Log message changes for debugging
        if (prevMessages.length !== messages.length) {
            console.log(`Messages state updated: ${prevMessages.length} -> ${messages.length} messages`);

            // Log the last message if available
            if (messages.length > 0) {
                const lastMsg = messages[messages.length - 1];
                console.log('Last message:', {
                    role: lastMsg.role,
                    content: lastMsg.content?.substring(0, 30) + (lastMsg.content?.length > 30 ? '...' : ''),
                    id: lastMsg.id
                });
            }
        }
    }, [messages]);

    useEffect(() => {
        loadingRef.current = loading;
    }, [loading]);

    useEffect(() => {
        sessionIdRef.current = sessionId;
    }, [sessionId]);

    /**
     * Add a status message
     */
    const addStatusMessage = useCallback((type, text) => {
        const timeString = new Date().toLocaleTimeString();
        setStatusMessages(prev => {
            const newMessages = [...prev, { type, text, time: timeString }];
            return newMessages.length > 10 ? newMessages.slice(-10) : newMessages;
        });
    }, []);

    /**
     * Initialize session
     */
    useEffect(() => {
        // Create a session
        const createSession = async () => {
            try {
                console.log('INIT DEBUG: Creating new session...');
                const response = await axios.post(`${SERVER_URL}/session`);
                if (response.data.success) {
                    console.log('INIT DEBUG: Session created successfully:', response.data.sessionId);
                    setSessionId(response.data.sessionId);
                    addStatusMessage('success', `Session created: ${response.data.sessionId}`);

                    // Initialize tools
                    console.log('INIT DEBUG: Initializing tools...');
                    await axios.get(`${SERVER_URL}/init`);

                    // Set stream status to waiting - this will trigger auto-start
                    console.log('INIT DEBUG: Setting stream status to waiting to trigger auto-start');
                    setStreamStatus('waiting');

                    // Take initial screenshot
                    takeScreenshot();
                } else {
                    setError(`Error creating session: ${response.data.error}`);
                }
            } catch (err) {
                console.error('INIT DEBUG: Error creating session:', err);
                setError(`Failed to create session: ${err.message}`);
            }
        };

        createSession();

        // Clean up on unmount
        return () => {
            if (pollTimerRef.current) clearTimeout(pollTimerRef.current);
            if (streamSourceRef.current) streamSourceRef.current.close();
        };
    }, [addStatusMessage]);

    /**
     * Find the last message with a specific role
     */
    const findLastMessage = useCallback((messages, role) => {
        for (let i = messages.length - 1; i >= 0; i--) {
            if (messages[i].role === role) return messages[i];
        }
        return null;
    }, []);

    /**
     * Check if the response is complete
     */
    const isResponseComplete = useCallback((messages) => {
        const lastAssistant = findLastMessage(messages, 'assistant');
        if (!lastAssistant) return false;

        // Check for explicit completion signal
        if (lastAssistant.finish_reason === 'stop') return true;

        // Tool call completion
        if (lastAssistant.tool_calls && lastAssistant.tool_calls.length > 0) {
            const toolCallIds = lastAssistant.tool_calls.map(tc => tc.id);
            const toolResponses = messages.filter(m =>
                (m.role === 'tool' || m.role === 'function') &&
                toolCallIds.includes(m.tool_call_id)
            );

            // All tool calls have been responded to
            if (toolResponses.length === toolCallIds.length) {
                // Find last tool response index
                const lastToolIndex = messages.findIndex(m => m === toolResponses[toolResponses.length - 1]);

                // Check for follow-up assistant message
                return messages.some((m, i) => i > lastToolIndex && m.role === 'assistant');
            }
        }

        // Content-based heuristics
        if (lastAssistant.content) {
            const hasSubstantialContent = lastAssistant.content.length > 50;
            const hasCompleteSentence = Boolean(lastAssistant.content.match(/[.!?]\s*$/));
            return hasSubstantialContent && hasCompleteSentence;
        }

        return false;
    }, [findLastMessage]);

    /**
     * Helper function to deduplicate messages
     */
    const deduplicateMessages = useCallback((messages) => {
        // Track seen messages by content and role
        const seen = new Map();
        const result = [];

        // Process in reverse to keep the most recent messages
        for (let i = messages.length - 1; i >= 0; i--) {
            const msg = messages[i];
            const key = `${msg.role}:${msg.content}`;

            // If we haven't seen this message yet, add it to the result
            if (!seen.has(key)) {
                seen.set(key, true);
                result.unshift(msg); // Add to beginning since we're processing in reverse
            }
        }

        return result;
    }, []);

    /**
     * Process server messages and remove duplicates
     */
    const processServerMessages = useCallback((serverMessages) => {
        // First deduplicate the server messages
        return deduplicateMessages(serverMessages);
    }, [deduplicateMessages]);

    /**
     * Poll for message updates
     */
    const pollForMessages = useCallback(async () => {
        console.log('POLL: Called with state:', {
            sessionId: !!sessionId,
            loading: loadingRef.current,
            hasExistingTimer: !!pollTimerRef.current,
            currentMessageCount: messagesRef.current.length
        });

        // Always clear any existing timer first to prevent duplicates
        if (pollTimerRef.current) {
            clearTimeout(pollTimerRef.current);
            pollTimerRef.current = null;
            console.log('POLL: Cleared existing poll timer');
        }

        // Exit if no session
        if (!sessionId) {
            console.log('POLL: Stopped - No sessionId available');
            return;
        }

        try {
            console.log('POLL: Fetching messages from server...');
            const response = await axios.get(
                `${SERVER_URL}/messages/${sessionId}?_t=${Date.now()}`,
                { timeout: 5000 }
            );

            if (response.data.success && response.data.messages) {
                // Process and deduplicate server messages
                const newMessages = processServerMessages(response.data.messages);
                const currentMessages = messagesRef.current;

                console.log('POLL: Received messages', {
                    server: newMessages.length,
                    client: currentMessages.length,
                    loading: loadingRef.current
                });

                // Force update messages with server data
                // Always update with server messages to ensure we get all assistant responses
                const lastUserMessage = currentMessages.length > 0 &&
                    currentMessages[currentMessages.length - 1].role === 'user' ?
                    currentMessages[currentMessages.length - 1] : null;

                // Check if the last user message is missing from the server response
                const shouldPreserveUserMessage = lastUserMessage &&
                    !newMessages.some(msg =>
                        msg.role === 'user' &&
                        msg.content === lastUserMessage.content
                    );

                let updatedMessages;
                if (shouldPreserveUserMessage) {
                    console.log('POLL: Preserving user message in UI');
                    updatedMessages = [...newMessages, lastUserMessage];
                } else {
                    updatedMessages = newMessages;
                }

                // Always update the messages state
                setMessages(updatedMessages);
                messagesRef.current = updatedMessages;
                console.log('POLL: Updated messages, count:', updatedMessages.length);

                // Check if we have an assistant message with content
                const lastMessage = newMessages[newMessages.length - 1];
                if (lastMessage && lastMessage.role === 'assistant' && lastMessage.content) {
                    setStreamingContent(lastMessage.content);
                    console.log('POLL: Updated streaming content from assistant');
                }

                // Check if response is complete
                const responseComplete = isResponseComplete(newMessages);
                if (responseComplete) {
                    console.log('POLL: Response complete, will stop polling');
                    setLoading(false);
                    loadingRef.current = false; // Update ref directly
                    setStreamingContent(''); // Clear streaming content
                    addStatusMessage('success', 'Response complete');

                    // Do one final poll after a short delay to ensure we catch any last messages
                    setTimeout(() => {
                        console.log('POLL: Final check for messages');
                        pollForMessages();
                    }, 1000);

                    return;
                }
            } else {
                console.warn('POLL: Server returned invalid data structure');
            }
        } catch (err) {
            console.error('POLL: Error polling for messages:', err);
            addStatusMessage('error', `Polling error: ${err.message}`);

            // Don't stop polling on error unless we've exceeded max retries
            // Just continue with the next poll cycle
        }

        // Always continue polling if we're in loading state
        if (loadingRef.current && sessionId) {
            console.log(`POLL: Scheduling next poll in ${POLL_INTERVAL}ms`);
            pollTimerRef.current = setTimeout(pollForMessages, POLL_INTERVAL);
        } else {
            // Only log if we're stopping due to loading state
            console.log('POLL: Not scheduling next poll - loading state is false');
        }
    }, [addStatusMessage, isResponseComplete, sessionId, processServerMessages, deduplicateMessages, setStreamingContent]);

    /**
     * Start polling when loading state changes
     */
    useEffect(() => {
        console.log('EFFECT: Loading state changed:', loading, 'Session:', !!sessionId);

        // When loading becomes true, ensure we start polling
        if (loading && sessionId) {
            console.log('EFFECT: Loading ON - Starting/continuing polling');

            // Keep ref in sync with state
            loadingRef.current = true;

            // Clear any existing timer to start fresh
            if (pollTimerRef.current) {
                clearTimeout(pollTimerRef.current);
                pollTimerRef.current = null;
                console.log('EFFECT: Cleared existing poll timer');
            }

            // Start polling - IMPORTANT: using a small delay helps prevent race conditions
            // This also ensures any previous polling operations have completed
            console.log('EFFECT: Starting polling with 100ms delay for stability');
            const startTimer = setTimeout(() => {
                if (sessionId && loadingRef.current) {
                    console.log('EFFECT: Starting poll cycle from loading effect');
                    pollForMessages();
                }
            }, 100);

            // Clean up
            return () => {
                clearTimeout(startTimer);
                if (pollTimerRef.current) {
                    clearTimeout(pollTimerRef.current);
                    pollTimerRef.current = null;
                    console.log('EFFECT: Cleaned up poll timer on effect cleanup');
                }
            };
        } else if (!loading) {
            // Keep ref in sync with state when loading is turned off
            loadingRef.current = false;
            console.log('EFFECT: Loading OFF - Refs updated');
        }
    }, [loading, sessionId, pollForMessages]);

    /**
     * Handle session expiration
     */
    const handleSessionExpired = useCallback(async () => {
        setError('Session expired. Creating a new session...');
        setSessionId(null);
        setLoading(false);

        try {
            const response = await axios.post(`${SERVER_URL}/session`);
            if (response.data.success) {
                setSessionId(response.data.sessionId);
                addStatusMessage('system', `New session created: ${response.data.sessionId}`);
                setError('Session recreated. Please send your message again.');
            } else {
                setError(`Failed to create new session: ${response.data.error}`);
            }
        } catch (err) {
            setError(`Failed to create new session: ${err.message}`);
        }
    }, [addStatusMessage]);

    /**
     * Handle sending a message
     */
    const handleSendMessage = useCallback(async (message) => {
        if (!message) return;

        console.log('==== SENDING NEW MESSAGE ====');

        // Force the loading state to true immediately (both state and ref)
        // This is critical to ensure polling starts correctly
        setLoading(true);
        loadingRef.current = true;
        console.log('handleSendMessage: Force-set loading state to TRUE');

        // Reset streaming content
        setStreamingContent('');

        // Create a new message object with a unique ID
        const userMessage = {
            id: `user-${Date.now()}`,
            role: 'user',
            content: message,
            created_at: new Date().toISOString(),
        };

        // Check if the same message already exists to prevent duplicates
        const existingMessages = messagesRef.current;
        const isDuplicate = existingMessages.some(msg =>
            msg.role === 'user' &&
            msg.content === message &&
            // Only consider recent messages (within last 5 seconds) as potential duplicates
            msg.id && msg.id.startsWith('user-') &&
            (Date.now() - parseInt(msg.id.split('-')[1])) < 5000
        );

        if (!isDuplicate) {
            // Only update UI with new message if it's not a duplicate
            const updatedMessages = [...existingMessages, userMessage];
            setMessages(updatedMessages);
            messagesRef.current = updatedMessages; // Directly update ref for immediate effect
            console.log('Added user message to UI');
        } else {
            console.log('Prevented duplicate user message');
        }

        try {
            // Check if we have a valid session before proceeding
            if (!sessionId) {
                await handleSessionExpired();
                if (!sessionId) {
                    throw new Error('Session creation failed');
                }
            }

            // Hard-terminate any existing polling to ensure a clean slate
            if (pollTimerRef.current) {
                console.log('Forcibly clearing existing poll timer before sending');
                clearTimeout(pollTimerRef.current);
                pollTimerRef.current = null;
            }

            // Send the message
            console.log('Sending message to server...');
            await axios.post(`${SERVER_URL}/chat/${sessionId}`, {
                message
            }, { timeout: 10000 });
            console.log('Message sent successfully to server');

            // CRITICAL: Double-check loading state is still true after network call
            // Sometimes React state updates can be processed during async operations
            if (!loadingRef.current) {
                console.log('WARNING: Loading state was reset during network call - forcing back to TRUE');
                setLoading(true);
                loadingRef.current = true;
            }

            // Explicitly start polling with immediate effect
            console.log('Explicitly starting poll cycle now...');
            pollForMessages();

            // Set a backup timer in case the first polling cycle fails
            const backupTimer = setTimeout(() => {
                if (loadingRef.current && sessionId) {
                    console.log('BACKUP: Starting additional poll cycle as backup');
                    pollForMessages();
                }
            }, 2000);

            // Clear backup timer after 5 seconds
            setTimeout(() => {
                clearTimeout(backupTimer);
            }, 5000);

        } catch (err) {
            console.error('Error sending message:', err);
            setLoading(false);
            loadingRef.current = false;

            if (err.response && err.response.status === 404) {
                addStatusMessage('error', 'Session expired, creating a new one...');
                await handleSessionExpired();
            } else {
                addStatusMessage('error', `Failed to send message: ${err.message}`);
            }
        }
    }, [sessionId, setLoading, setMessages, setStreamingContent, pollForMessages, handleSessionExpired, addStatusMessage]);

    /**
     * Take a screenshot
     */
    const takeScreenshot = useCallback(async () => {
        if (!sessionIdRef.current) return;

        try {
            const response = await axios.get(`${SERVER_URL}/screenshot`, {
                params: { sessionId: sessionIdRef.current, _t: Date.now() }
            });

            if (response.data && response.data.image) {
                setBrowserImage(response.data.image);
                addStatusMessage('info', 'Screenshot updated');
            }
        } catch (err) {
            addStatusMessage('warning', `Screenshot failed: ${err.message}`);
        }
    }, [addStatusMessage]);

    /**
     * Basic stream cleanup (separate from full stopStream)
     */
    const cleanupStream = useCallback(() => {
        if (streamSourceRef.current) {
            try {
                console.log('Closing stream connection');

                // Close the EventSource
                if (streamSourceRef.current.close) {
                    streamSourceRef.current.close();
                }

                // Notify server about disconnection
                const currentSession = sessionIdRef.current;
                if (currentSession) {
                    axios.post(`${SERVER_URL}/stream-disconnect`, {
                        sessionId: currentSession,
                        timestamp: Date.now()
                    }).catch(err => {
                        console.error('Failed to notify about stream disconnect:', err);
                    });
                }

                streamSourceRef.current = null;
            } catch (err) {
                console.error('Error cleaning up stream:', err);
            }
        }
    }, []);

    /**
     * Start browser stream 
     */
    const startStream = useCallback((options = {}) => {
        if (!sessionId || streaming) {
            console.log('STREAM DEBUG: Cannot start stream - sessionId or streaming conditions not met',
                { hasSession: !!sessionId, isStreaming: streaming });
            return;
        }

        setStreamStatus('connecting');
        addStatusMessage('info', 'Starting browser stream...');
        console.log('STREAM DEBUG: Starting stream with session ID:', sessionId);

        // Connection timeout ID for cleanup
        let connectionTimeoutId = null;

        try {
            // Close any existing stream
            cleanupStream();

            // First verify session is valid before attempting to stream
            console.log('STREAM DEBUG: Verifying session is valid before streaming');

            axios.get(`${SERVER_URL}/health?sessionId=${sessionId}`)
                .then(() => {
                    console.log('STREAM DEBUG: Session verification successful, creating EventSource');

                    // Direct EventSource approach - more reliable than iframe
                    const streamUrl = `${SERVER_URL}/browser-stream/${sessionId}`;
                    console.log('STREAM DEBUG: EventSource URL:', streamUrl);

                    // Verbose debug information
                    console.log('STREAM DEBUG: Browser info:', navigator.userAgent);
                    console.log('STREAM DEBUG: Creating EventSource...');

                    const source = new EventSource(streamUrl);
                    console.log('STREAM DEBUG: EventSource created, readyState:', source.readyState,
                        '(0=connecting, 1=open, 2=closed)');
                    console.log('STREAM DEBUG: Setting up EventSource handlers...');

                    // Set connection timeout
                    connectionTimeoutId = setTimeout(() => {
                        console.error('STREAM DEBUG: Timeout triggered - connection timed out after 10 seconds');
                        console.error('STREAM DEBUG: EventSource readyState at timeout:', source.readyState);

                        addStatusMessage('error', 'Stream connection timed out - will retry');
                        if (source && source.readyState !== 2) { // Not closed
                            console.log('STREAM DEBUG: Closing EventSource due to timeout');
                            source.close();
                        }

                        // Auto-retry after short delay
                        setTimeout(() => {
                            if (sessionId && !streaming) {
                                console.log('STREAM DEBUG: Auto-retrying stream connection...');
                                startStream();
                            }
                        }, 2000);
                    }, 10000);

                    // Handle connection open
                    source.onopen = () => {
                        console.log('STREAM DEBUG: EventSource.onopen fired! Connection succeeded.');
                        console.log('STREAM DEBUG: EventSource readyState in onopen:', source.readyState);

                        clearTimeout(connectionTimeoutId);
                        connectionTimeoutId = null;

                        setStreamStatus('active');
                        setStreaming(true);
                        addStatusMessage('success', 'Stream connected successfully');
                    };

                    // Handle messages
                    source.onmessage = (event) => {
                        console.log('STREAM DEBUG: Received message event:', event.type, 'Data length:', event.data?.length || 0);

                        // Process image data
                        if (event.data && event.data.startsWith('data:image')) {
                            console.log('STREAM DEBUG: Image received, length:', event.data.length);
                            setBrowserImage(event.data);
                        } else {
                            console.log('STREAM DEBUG: Received non-image data:', event.data);
                        }
                    };

                    // Handle specific events
                    source.addEventListener('status', (event) => {
                        console.log('STREAM DEBUG: Received status event:', event.type, 'Data:', event.data);

                        try {
                            const data = JSON.parse(event.data);
                            console.log('STREAM DEBUG: Status update from stream:', data);
                            addStatusMessage(data.type || 'info', data.message || 'Stream update');
                        } catch (e) {
                            console.error('STREAM DEBUG: Error parsing status event:', e);
                        }
                    });

                    // Handle errors
                    source.onerror = (error) => {
                        console.error('STREAM DEBUG: EventSource error:', error);
                        console.error('STREAM DEBUG: EventSource readyState in onerror:', source.readyState);

                        if (source.readyState === 2) { // CLOSED
                            console.error('STREAM DEBUG: EventSource connection CLOSED');
                            addStatusMessage('error', 'Stream connection closed by server');
                            if (connectionTimeoutId) {
                                clearTimeout(connectionTimeoutId);
                                connectionTimeoutId = null;
                            }
                            setStreaming(false);
                            setStreamStatus('error');
                            // Try fallback polling
                            tryPollingFallback();
                        } else {
                            console.warn('STREAM DEBUG: EventSource error but connection still open');
                            addStatusMessage('warning', 'Stream connection error - will try to continue');
                        }
                    };

                    // Store reference for cleanup
                    streamSourceRef.current = source;
                    console.log('STREAM DEBUG: EventSource setup complete');
                })
                .catch(err => {
                    console.error('STREAM DEBUG: Session verification failed:', err);
                    addStatusMessage('error', `Cannot start stream - session verification failed: ${err.message}`);

                    if (connectionTimeoutId) {
                        clearTimeout(connectionTimeoutId);
                    }

                    setStreamStatus('error');
                    // Try to create a new session
                    if (err.response && err.response.status === 404) {
                        console.log('STREAM DEBUG: Session not found, will try to create a new one');
                        handleSessionExpired();
                    }
                });
        } catch (err) {
            console.error('STREAM DEBUG: Fatal error creating stream connection:', err);
            addStatusMessage('error', `Stream connection error: ${err.message}`);
            setStreamStatus('error');

            // Clear timeout
            if (connectionTimeoutId) {
                clearTimeout(connectionTimeoutId);
                connectionTimeoutId = null;
            }

            // Fall back to polling
            tryPollingFallback();
        }
    }, [sessionId, streaming, streamStatus, addStatusMessage, cleanupStream, handleSessionExpired]);

    /**
     * Fall back to polling for screenshots
     */
    const tryPollingFallback = useCallback(() => {
        console.log('Using screenshot polling as fallback');
        addStatusMessage('info', 'Using screenshot polling instead of streaming');
        setStreaming(false);
        setStreamStatus('inactive');

        // Take an immediate screenshot
        takeScreenshot();

        // Set up polling interval
        const pollInterval = setInterval(() => {
            if (sessionIdRef.current) {
                console.log('Polling for screenshot update');
                takeScreenshot();
            } else {
                clearInterval(pollInterval);
            }
        }, 5000); // Poll every 5 seconds

        // Store interval for cleanup
        streamSourceRef.current = {
            close: () => {
                clearInterval(pollInterval);
                streamSourceRef.current = null;
            }
        };
    }, [addStatusMessage, takeScreenshot]);

    /**
     * Stop browser stream
     */
    const stopStream = useCallback(() => {
        console.log('Stopping stream');

        // Just use our cleanupStream helper
        cleanupStream();

        // Update state
        setStreaming(false);
        setStreamStatus('inactive');
        addStatusMessage('info', 'Stream connection closed');
    }, [addStatusMessage, cleanupStream]);

    /**
     * Ping server to check connection
     */
    const pingServer = useCallback(async () => {
        try {
            addStatusMessage('info', 'Checking server connection...');
            const startTime = Date.now();

            const response = await axios.get(`${SERVER_URL}/health?_t=${Date.now()}`, {
                timeout: 5000
            });

            const latency = Date.now() - startTime;

            if (response.data && response.data.success) {
                addStatusMessage('success', `Server is healthy (${latency}ms)`);
                console.log('Server health check successful:', response.data);
                return true;
            } else {
                addStatusMessage('warning', 'Server returned invalid response');
                console.warn('Server health check returned:', response.data);
                return false;
            }
        } catch (err) {
            console.error('Server ping failed:', err);
            addStatusMessage('error', `Server connection error: ${err.message}`);
            return false;
        }
    }, [addStatusMessage]);

    /**
     * Restart stream with clean connection
     */
    const restartStream = useCallback(() => {
        addStatusMessage('info', 'Restarting stream connection...');
        stopStream();

        // Wait a short delay before restarting
        setTimeout(() => {
            // Check server health before restarting
            pingServer().then(isHealthy => {
                if (isHealthy) {
                    startStream();
                } else {
                    addStatusMessage('error', 'Cannot restart stream - server connection issues');
                }
            });
        }, 1000);
    }, [stopStream, startStream, pingServer, addStatusMessage]);

    /**
     * Manual scroll to bottom function
     */
    const scrollToBottom = useCallback(() => {
        if (chatContainerRef.current) {
            // Smooth scroll to the very bottom
            const container = chatContainerRef.current;
            if (container) {
                container.scrollTo({
                    top: container.scrollHeight,
                    behavior: 'smooth'
                });

                // Hide scroll button after scrolling completes
                setTimeout(() => {
                    const { scrollTop, scrollHeight, clientHeight } = container;
                    const isAtBottom = scrollHeight - scrollTop - clientHeight < 50;
                    setShowScrollButton(!isAtBottom);
                }, 500);
            }
        }
    }, []);

    /**
     * Handle chat container scroll to show/hide scroll button
     */
    const handleChatScroll = useCallback(() => {
        if (!chatContainerRef.current) return;

        const container = chatContainerRef.current;
        const { scrollTop, scrollHeight, clientHeight } = container;

        // Calculate if there's content to scroll
        const hasScrollableContent = scrollHeight > clientHeight + 50;

        // Calculate how far we are from the bottom
        const distanceFromBottom = scrollHeight - scrollTop - clientHeight;

        // Only show button when:
        // 1. There is enough content to scroll AND
        // 2. User is not already at the bottom
        const isNearBottom = distanceFromBottom < 50;
        setShowScrollButton(hasScrollableContent && !isNearBottom);
    }, []);

    // Initialize scroll button state on component mount and when messages change
    useEffect(() => {
        // Short delay to ensure content is rendered
        setTimeout(() => {
            if (chatContainerRef.current) {
                const container = chatContainerRef.current;
                const { scrollTop, scrollHeight, clientHeight } = container;

                // Show button only if there's content to scroll and not at bottom
                const hasScrollableContent = scrollHeight > clientHeight + 50;
                const isNearBottom = scrollHeight - scrollTop - clientHeight < 50;
                setShowScrollButton(hasScrollableContent && !isNearBottom);
            }
        }, 100);
    }, [messages]);

    // Add scroll event listener to chat container
    useEffect(() => {
        const chatContainer = chatContainerRef.current;
        if (chatContainer) {
            chatContainer.addEventListener('scroll', handleChatScroll);
        }

        return () => {
            if (chatContainer) {
                chatContainer.removeEventListener('scroll', handleChatScroll);
            }
        };
    }, [handleChatScroll]);

    /**
     * Auto-start stream when session is ready
     */
    useEffect(() => {
        if (sessionId && !streaming && streamStatus === 'waiting') {
            console.log('STREAM DEBUG: Auto-starting stream due to valid session:', sessionId);

            // Short delay to ensure everything is ready
            setTimeout(() => {
                console.log('STREAM DEBUG: Starting stream after delay');
                startStream();
            }, 500);

            // If stream fails to start, take a screenshot as a fallback
            const fallbackTimer = setTimeout(() => {
                if (!streaming && sessionId) {
                    console.log('STREAM DEBUG: Stream failed to auto-start, taking screenshot as fallback');
                    takeScreenshot();
                }
            }, 3000);

            return () => clearTimeout(fallbackTimer);
        }
    }, [sessionId, streaming, streamStatus, startStream, takeScreenshot]);

    /**
     * Monitor server health when streaming
     */
    useEffect(() => {
        // Only run health monitoring when streaming is active
        if (!streaming || !sessionId) return;

        console.log('STREAM DEBUG: Starting server health monitoring');

        // Check server health every 5 seconds
        const healthCheckInterval = setInterval(async () => {
            try {
                const response = await axios.get(`${SERVER_URL}/health?_t=${Date.now()}`, {
                    timeout: 3000
                });

                if (response.data && response.data.success) {
                    console.log('STREAM DEBUG: Server health check passed');
                } else {
                    console.warn('STREAM DEBUG: Server health check returned unexpected response', response.data);
                }
            } catch (err) {
                console.error('STREAM DEBUG: Server health check failed:', err);
                addStatusMessage('error', `Server connection error: ${err.message}`);

                // If we get an error during health check while streaming, 
                // it suggests the server connection is unstable
                if (streaming) {
                    console.error('STREAM DEBUG: Triggering stream restart due to failed health check');
                    restartStream();
                }
            }
        }, 5000);

        // Clean up on unmount or when streaming stops
        return () => {
            clearInterval(healthCheckInterval);
            console.log('STREAM DEBUG: Stopping server health monitoring');
        };
    }, [sessionId, streaming, addStatusMessage, restartStream]);

    /**
     * Toggle technical messages
     */
    const toggleTechnicalMessages = useCallback(() => {
        setShowTechnicalMessages(prev => !prev);
    }, []);

    /**
     * Toggle preview section
     */
    const togglePreview = useCallback(() => {
        if (streaming && previewVisible) {
            stopStream();
        }
        setPreviewVisible(prev => !prev);
    }, [streaming, previewVisible, stopStream]);

    // Auto-scroll to bottom when new messages arrive if user is already near bottom
    useEffect(() => {
        if (!chatContainerRef.current) return;

        const container = chatContainerRef.current;
        const { scrollTop, scrollHeight, clientHeight } = container;

        // Use a larger threshold to determine if auto-scroll should happen
        const isNearBottom = scrollHeight - scrollTop - clientHeight < 200;

        // Only auto-scroll if user is already at or near bottom
        if (isNearBottom) {
            setTimeout(() => {
                if (messagesEndRef.current) {
                    messagesEndRef.current.scrollIntoView({
                        behavior: 'smooth'
                    });
                }
            }, 100);
        }
    }, [messages]);

    // Add function to periodically clean up duplicate messages
    useEffect(() => {
        // Skip if we don't have enough messages to deduplicate
        if (messagesRef.current.length <= 2) return;

        // Check for duplicates
        const currentMessages = messagesRef.current;
        const deduplicated = deduplicateMessages(currentMessages);

        // If we found and removed duplicates, update the messages
        if (deduplicated.length < currentMessages.length) {
            console.log(`Removing ${currentMessages.length - deduplicated.length} duplicate messages`);
            setMessages(deduplicated);
        }
    }, [messages, deduplicateMessages]);

    return (
        <div className="app-container">
            <header className="app-header">
                <h1>🤖 Browser Automation Assistant</h1>
                <div style={{ display: 'flex', gap: '10px' }}>
                    <button
                        className="toggle-preview-button"
                        onClick={togglePreview}
                    >
                        {previewVisible ? 'Hide Preview' : 'Show Preview'}
                    </button>
                    <button
                        className="ping-button"
                        onClick={pingServer}
                        style={{
                            padding: '5px 10px',
                            cursor: 'pointer'
                        }}
                    >
                        Ping Server
                    </button>
                </div>
            </header>

            <main className="main-content">
                {/* Chat Section */}
                <div className="chat-section">
                    <div className="chat-header">
                        <h2>Chat</h2>
                        <button
                            className="toggle-technical-button"
                            onClick={toggleTechnicalMessages}
                        >
                            {showTechnicalMessages ? 'Hide Technical Details' : 'Show Technical Details'}
                        </button>
                    </div>

                    <div className="chat-container" ref={chatContainerRef}>
                        {messages
                            .filter(msg =>
                                ['user', 'assistant'].includes(msg.role) ||
                                (showTechnicalMessages && ['tool', 'system', 'function'].includes(msg.role))
                            )
                            .map((message, index) => (
                                <div key={index} className={`message ${message.role}`}>
                                    <div className="message-role">
                                        {message.role === 'user' && <span className="message-icon">👤</span>}
                                        {message.role === 'assistant' && <span className="message-icon">🤖</span>}
                                        {message.role !== 'user' && message.role !== 'assistant' && (
                                            message.role === 'function' ? 'tool-result' : message.role
                                        )}
                                    </div>
                                    <div className="message-content">
                                        {message.role === 'function' || message.role === 'tool' ? (
                                            <pre className="tool-content">
                                                {typeof message.content === 'string'
                                                    ? message.content
                                                    : JSON.stringify(message.content, null, 2)}
                                            </pre>
                                        ) : (
                                            <div>{message.content}</div>
                                        )}

                                        {/* Display tool calls */}
                                        {message.tool_calls && (
                                            <div className="tool-calls">
                                                <div className="tool-call-header">Tool Calls:</div>
                                                {message.tool_calls.map((tool, toolIndex) => (
                                                    <div key={toolIndex} className="tool-call">
                                                        <div className="tool-name">
                                                            {tool.function?.name || 'Unknown Tool'}
                                                        </div>
                                                        <pre className="tool-args">
                                                            {tool.function?.arguments || '{}'}
                                                        </pre>
                                                    </div>
                                                ))}
                                            </div>
                                        )}
                                    </div>
                                </div>
                            ))}

                        {/* Error message */}
                        {error && (
                            <div className="message error">
                                <div className="message-role">Error</div>
                                <div className="message-content">{error}</div>
                            </div>
                        )}

                        {/* Streaming effect instead of loading spinner */}
                        {loading && (
                            <div className="message streaming">
                                <div className="message-role">
                                    <span className="message-icon">🤖</span>
                                    assistant
                                </div>
                                <div className="message-content">
                                    {streamingContent ? (
                                        <div style={{ display: 'flex', alignItems: 'center' }}>
                                            <span>{streamingContent}</span>
                                            <span className="blink-cursor"></span>
                                        </div>
                                    ) : (
                                        <div className="typing-indicator">
                                            <span className="typing-dot"></span>
                                            <span className="typing-dot"></span>
                                            <span className="typing-dot"></span>
                                        </div>
                                    )}
                                </div>
                            </div>
                        )}

                        {/* Element for scrolling to bottom */}
                        <div ref={messagesEndRef} style={{ float: 'left', clear: 'both', height: '50px', width: '100%' }} />

                        {/* Scroll to bottom button in sticky wrapper */}
                        {showScrollButton && (
                            <div className="scroll-button-wrapper">
                                <button
                                    className="scroll-button"
                                    onClick={scrollToBottom}
                                    title="Scroll to bottom"
                                >
                                    ↓
                                </button>
                            </div>
                        )}
                    </div>

                    {/* Message input form */}
                    <form className="input-container" onSubmit={(e) => {
                        e.preventDefault();

                        const trimmedInput = inputValue.trim();
                        console.log('Form submitted with input:', trimmedInput);

                        if (trimmedInput && sessionId) {
                            console.log('Input valid, sending message and clearing input');
                            // Clear input right away to prevent double-sending
                            setInputValue('');
                            setError(null);
                            // Then send the message
                            handleSendMessage(trimmedInput);
                        } else {
                            if (!trimmedInput) {
                                console.log('Empty input, not sending');
                            }
                            if (!sessionId) {
                                console.log('No valid session, not sending');
                                setError('No valid session. Please wait for a session to be created.');
                            }
                        }
                    }}>
                        <input
                            type="text"
                            value={inputValue}
                            onChange={(e) => setInputValue(e.target.value)}
                            placeholder="Type your message..."
                            className="message-input"
                            disabled={loading || !sessionId}
                        />
                        <button
                            type="submit"
                            className="send-button"
                            disabled={loading || !sessionId || !inputValue.trim()}
                        >
                            Send
                        </button>
                    </form>
                </div>

                {/* Preview Section */}
                {previewVisible && (
                    <div className="preview-section">
                        <h2 className="preview-title">
                            Browser Preview
                            <div className="preview-controls">
                                {streaming ? (
                                    <>
                                        <button
                                            onClick={stopStream}
                                            className="stream-button stop"
                                            disabled={!sessionId}
                                        >
                                            Stop Stream
                                        </button>
                                        <button
                                            onClick={restartStream}
                                            className="stream-button restart"
                                            disabled={!sessionId}
                                        >
                                            Restart Stream
                                        </button>
                                    </>
                                ) : (
                                    <button
                                        onClick={startStream}
                                        className="stream-button start"
                                        disabled={!sessionId}
                                    >
                                        Start Stream
                                    </button>
                                )}
                                <button
                                    onClick={takeScreenshot}
                                    className="refresh-preview-button"
                                    disabled={!sessionId || streaming}
                                >
                                    Take Screenshot
                                </button>
                            </div>
                        </h2>

                        {/* Stream status indicator */}
                        <div
                            className={`stream-status ${streamStatus} ${streaming ? 'pulsing' : ''}`}
                            onClick={streamStatus === 'error' ? restartStream : undefined}
                            style={streamStatus === 'error' ? { cursor: 'pointer' } : {}}
                        >
                            {streamStatus === 'waiting' ? 'Ready' :
                                streamStatus === 'connecting' ? 'Connecting...' :
                                    streamStatus === 'active' ? 'Stream active' :
                                        streamStatus === 'error' ? 'Stream error (click to restart)' :
                                            streamStatus.charAt(0).toUpperCase() + streamStatus.slice(1)}
                        </div>

                        {/* Browser preview image */}
                        <div className="browser-preview">
                            {browserImage ? (
                                <img
                                    src={browserImage}
                                    alt="Browser preview"
                                    className="browser-image"
                                    title={streaming ? "Live stream" : "Static screenshot"}
                                />
                            ) : (
                                <div className="no-preview">
                                    No browser activity yet
                                </div>
                            )}
                        </div>

                        {/* Status log */}
                        <div className="status-log">
                            <h3>Status Log</h3>
                            <div className="status-messages">
                                {statusMessages.length === 0 ? (
                                    <div className="status-message info">
                                        <span className="status-time">--:--:--</span>
                                        <span className="status-text">Waiting for activity...</span>
                                    </div>
                                ) : (
                                    statusMessages.map((status, index) => (
                                        <div key={index} className={`status-message ${status.type}`}>
                                            <span className="status-time">{status.time}</span>
                                            <span className="status-text">{status.text}</span>
                                        </div>
                                    ))
                                )}
                            </div>
                        </div>
                    </div>
                )}
            </main>
        </div>
    );
}

export default App;
